import json
import re
from datetime import datetime, timezone, timedelta

JST = timezone(timedelta(hours=9))

MENU = [
    {'id': 'crepe', 'name': '台湾風クレープ', 'price': 350, 'sold_out': False},
    {'id': 'radish', 'name': '大根餅', 'price': 400, 'sold_out': False},
    {'id': 'noodle', 'name': '鉄板麺', 'price': 550, 'sold_out': False},
    {'id': 'nugget', 'name': 'チキンナゲット', 'price': 450, 'sold_out': False},
    {'id': 'milktea', 'name': 'ミルクティー', 'price': 300, 'sold_out': False},
    {'id': 'soymilk', 'name': '豆乳', 'price': 250, 'sold_out': False},
]
MENU_BY_ID = {m['id']: m for m in MENU}

STATUSES = ['未着手', '調理中', '完了']
ORDER_TYPES = ['店内', '持ち帰り']

_orders = []
_next_id = 1

ORDER_ID_RE = re.compile(r'^/orders/([0-9]+)$')
MENU_ID_RE = re.compile(r'^/menu/([A-Za-z0-9_-]+)$')


def _now():
    return datetime.now(JST)


def _parse_body(body):
    if not body or not body.strip():
        return {}, None
    try:
        data = json.loads(body.decode('utf-8'))
    except (ValueError, UnicodeDecodeError):
        return None, 'リクエストのJSON形式が正しくありません。'
    if not isinstance(data, dict):
        return None, 'リクエストはJSONオブジェクトで送信してください。'
    return data, None


def _to_int(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        s = value.strip()
        if s.isascii() and s.isdigit():
            return int(s)
    return None


def _public(order):
    return {
        'id': order['id'],
        'table': order['table'],
        'order_type': order['order_type'],
        'items': [dict(i) for i in order['items']],
        'total': order['total'],
        'status': order['status'],
        'created_at': order['created_at'],
    }


def _update_menu_item(item_id, body):
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}
    item = MENU_BY_ID.get(item_id)
    if item is None:
        return 404, {'error': '商品が見つかりません。'}
    sold_out = data.get('sold_out')
    if not isinstance(sold_out, bool):
        return 400, {'error': '品切れ状態は true または false で指定してください。'}
    item['sold_out'] = sold_out
    return 200, {'item': dict(item)}


def _create_order(body):
    global _next_id
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}

    table = _to_int(data.get('table'))
    if table is None or table < 1 or table > 999:
        return 400, {'error': 'テーブル番号は1〜999の整数で指定してください。'}

    order_type = data.get('order_type')
    if not isinstance(order_type, str) or order_type not in ORDER_TYPES:
        return 400, {'error': '注文区分は「店内」か「持ち帰り」で指定してください。'}

    items = data.get('items')
    if not isinstance(items, list) or not items:
        return 400, {'error': '商品を1つ以上指定してください。'}
    if len(items) > 50:
        return 400, {'error': '商品の種類が多すぎます。'}

    merged = {}
    order_ids = []
    for it in items:
        if not isinstance(it, dict):
            return 400, {'error': '商品の指定が正しくありません。'}
        item_id = it.get('id')
        if not isinstance(item_id, str) or item_id not in MENU_BY_ID:
            return 400, {'error': '存在しない商品が含まれています。'}
        qty = _to_int(it.get('quantity'))
        if qty is None or qty < 1 or qty > 99:
            return 400, {'error': '数量は1〜99の整数で指定してください。'}
        if item_id not in merged:
            merged[item_id] = 0
            order_ids.append(item_id)
        merged[item_id] += qty
        if merged[item_id] > 99:
            return 400, {'error': '同じ商品の数量は99までです。'}

    for item_id in order_ids:
        if MENU_BY_ID[item_id]['sold_out']:
            return 409, {'error': '「' + MENU_BY_ID[item_id]['name'] + '」は品切れです。'}

    lines = []
    total = 0
    for item_id in order_ids:
        m = MENU_BY_ID[item_id]
        qty = merged[item_id]
        lines.append({
            'id': m['id'],
            'name': m['name'],
            'price': m['price'],
            'quantity': qty,
        })
        total += m['price'] * qty

    now = _now()
    order = {
        'id': _next_id,
        'table': table,
        'order_type': order_type,
        'items': lines,
        'total': total,
        'status': STATUSES[0],
        'created_at': now.isoformat(timespec='seconds'),
        'date': now.strftime('%Y-%m-%d'),
    }
    _next_id += 1
    _orders.append(order)
    return 201, {'order': _public(order)}


def _list_orders(body):
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}
    status = data.get('status')
    if status is not None and status != '':
        if status not in STATUSES:
            return 400, {'error': '状態の指定が正しくありません。'}
        selected = [o for o in _orders if o['status'] == status]
    else:
        selected = list(_orders)
    selected.sort(key=lambda o: (o['created_at'], o['id']))
    return 200, {'orders': [_public(o) for o in selected]}


def _update_order(order_id, body):
    data, err = _parse_body(body)
    if err:
        return 400, {'error': err}
    order = None
    for o in _orders:
        if o['id'] == order_id:
            order = o
            break
    if order is None:
        return 404, {'error': '注文が見つかりません。'}

    idx = STATUSES.index(order['status'])
    if idx >= len(STATUSES) - 1:
        return 409, {'error': 'この注文はすでに完了しています。'}
    expected = STATUSES[idx + 1]

    requested = data.get('status')
    if requested is not None and requested != expected:
        if requested not in STATUSES:
            return 400, {'error': '状態の指定が正しくありません。'}
        return 409, {'error': '状態は「未着手」→「調理中」→「完了」の順にのみ変更できます。'}

    order['status'] = expected
    return 200, {'order': _public(order)}


def _sales_today():
    today = _now().strftime('%Y-%m-%d')
    todays = [o for o in _orders if o['date'] == today]

    counts = {}
    for o in todays:
        for it in o['items']:
            counts[it['id']] = counts.get(it['id'], 0) + it['quantity']

    ranking = []
    for m in MENU:
        if m['id'] in counts and counts[m['id']] > 0:
            ranking.append({'id': m['id'], 'name': m['name'], 'quantity': counts[m['id']]})
    # stable sort keeps menu order for ties
    ranking.sort(key=lambda r: -r['quantity'])

    return 200, {
        'date': today,
        'order_count': len(todays),
        'total_sales': sum(o['total'] for o in todays),
        'top_items': ranking[:3],
    }


def handle(method, path, body):
    method = (method or '').upper()
    path = path or '/'
    if not path.startswith('/'):
        path = '/' + path
    if len(path) > 1:
        path = path.rstrip('/')

    if path == '/health':
        if method != 'GET':
            return 405, {'error': '許可されていないメソッドです。'}
        return 200, {'status': 'ok'}

    if path == '/menu':
        if method != 'GET':
            return 405, {'error': '許可されていないメソッドです。'}
        return 200, {'menu': [dict(m) for m in MENU]}

    menu_match = MENU_ID_RE.match(path)
    if menu_match:
        if method != 'PATCH':
            return 405, {'error': '許可されていないメソッドです。'}
        return _update_menu_item(menu_match.group(1), body)

    if path == '/orders':
        if method == 'POST':
            return _create_order(body)
        if method == 'GET':
            return _list_orders(body)
        return 405, {'error': '許可されていないメソッドです。'}

    match = ORDER_ID_RE.match(path)
    if match:
        if method != 'PATCH':
            return 405, {'error': '許可されていないメソッドです。'}
        return _update_order(int(match.group(1)), body)

    if path == '/sales/today':
        if method != 'GET':
            return 405, {'error': '許可されていないメソッドです。'}
        return _sales_today()

    return 404, {'error': '見つかりません。'}

