(function () {
  'use strict';

  var STATUS_NEXT = { '未着手': '調理中', '調理中': '完了' };
  var STATUS_BUTTON = { '未着手': '調理を開始', '調理中': '完了にする' };
  var STATUS_CLASS = { '未着手': 'status-todo', '調理中': 'status-doing', '完了': 'status-done' };
  var TYPE_CLASS = { '店内': 'type-dine', '持ち帰り': 'type-take' };
  var REFRESH_MS = 5000;

  var menu = [];
  var quantities = {};
  var currentTab = 'order';

  function $(id) { return document.getElementById(id); }

  function yen(n) { return Number(n).toLocaleString('ja-JP') + '円'; }

  function api(path, options) {
    options = options || {};
    var init = { method: options.method || 'GET', headers: {} };
    if (options.body !== undefined) {
      init.headers['Content-Type'] = 'application/json';
      init.body = JSON.stringify(options.body);
    }
    return fetch('api/' + path, init).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (data) {
        if (!res.ok) {
          throw new Error(data.error || 'エラーが発生しました (' + res.status + ')');
        }
        return data;
      });
    });
  }

  function setMessage(id, text, isError) {
    var el = $(id);
    el.textContent = text || '';
    el.className = 'message' + (text ? (isError ? ' error' : ' ok') : '');
  }

  /* ---------- tabs ---------- */
  function showTab(name) {
    currentTab = name;
    var tabs = document.querySelectorAll('.tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].classList.toggle('active', tabs[i].getAttribute('data-tab') === name);
    }
    var panels = document.querySelectorAll('.panel');
    for (var j = 0; j < panels.length; j++) {
      panels[j].classList.toggle('active', panels[j].id === 'tab-' + name);
    }
    refresh();
  }

  /* ---------- order tab ---------- */
  function cartTotal() {
    var total = 0;
    menu.forEach(function (m) {
      if (!m.sold_out) { total += m.price * (quantities[m.id] || 0); }
    });
    return total;
  }

  function updateCart() {
    menu.forEach(function (m) {
      var q = $('qty-' + m.id);
      if (q) { q.textContent = String(quantities[m.id] || 0); }
    });
    $('cart-total').textContent = yen(cartTotal());
  }

  function changeQty(id, delta) {
    var q = (quantities[id] || 0) + delta;
    if (q < 0) { q = 0; }
    if (q > 99) { q = 99; }
    quantities[id] = q;
    updateCart();
  }

  function renderMenu() {
    var list = $('menu-list');
    list.textContent = '';
    menu.forEach(function (m) {
      var li = document.createElement('li');
      li.className = 'menu-item' + (m.sold_out ? ' sold-out' : '');

      var info = document.createElement('div');
      info.className = 'menu-info';
      var name = document.createElement('span');
      name.className = 'menu-name';
      name.textContent = m.name;
      var price = document.createElement('span');
      price.className = 'menu-price';
      price.textContent = yen(m.price);
      info.appendChild(name);
      info.appendChild(price);

      var ctl = document.createElement('div');
      ctl.className = 'qty-control';
      if (m.sold_out) {
        var tag = document.createElement('span');
        tag.className = 'sold-out-tag';
        tag.textContent = '品切れ';
        ctl.appendChild(tag);
      }
      var minus = document.createElement('button');
      minus.type = 'button';
      minus.textContent = '−';
      minus.disabled = !!m.sold_out;
      minus.setAttribute('aria-label', m.name + 'を減らす');
      minus.addEventListener('click', function () { changeQty(m.id, -1); });
      var qty = document.createElement('span');
      qty.id = 'qty-' + m.id;
      qty.className = 'qty';
      qty.textContent = '0';
      var plus = document.createElement('button');
      plus.type = 'button';
      plus.textContent = '+';
      plus.disabled = !!m.sold_out;
      plus.setAttribute('aria-label', m.name + 'を増やす');
      plus.addEventListener('click', function () { changeQty(m.id, 1); });
      ctl.appendChild(minus);
      ctl.appendChild(qty);
      ctl.appendChild(plus);

      li.appendChild(info);
      li.appendChild(ctl);
      list.appendChild(li);
    });
    updateCart();
  }

  function renderStock() {
    var list = $('stock-list');
    list.textContent = '';
    menu.forEach(function (m) {
      var li = document.createElement('li');
      li.className = 'stock-item' + (m.sold_out ? ' sold-out' : '');

      var name = document.createElement('span');
      name.className = 'stock-name';
      name.textContent = m.name;

      var state = document.createElement('span');
      state.className = 'stock-state';
      state.textContent = m.sold_out ? '品切れ' : '販売中';

      var b = document.createElement('button');
      b.type = 'button';
      b.className = m.sold_out ? 'primary' : 'secondary';
      b.textContent = m.sold_out ? '販売を再開' : '品切れにする';
      b.addEventListener('click', function () { toggleSoldOut(m, b); });

      li.appendChild(name);
      li.appendChild(state);
      li.appendChild(b);
      list.appendChild(li);
    });
  }

  function loadMenu() {
    return api('menu').then(function (data) {
      menu = data.menu || [];
      menu.forEach(function (m) {
        if (!(m.id in quantities) || m.sold_out) { quantities[m.id] = 0; }
      });
      renderMenu();
      renderStock();
    }).catch(function (e) {
      setMessage('order-message', 'メニューを読み込めませんでした: ' + e.message, true);
    });
  }

  function toggleSoldOut(m, btn) {
    btn.disabled = true;
    api('menu/' + m.id, { method: 'PATCH', body: { sold_out: !m.sold_out } }).then(function () {
      setMessage('stock-message', '', false);
      return loadMenu();
    }).catch(function (e) {
      setMessage('stock-message', '品切れ状態を更新できませんでした: ' + e.message, true);
      btn.disabled = false;
    });
  }

  function selectedOrderType() {
    var radios = document.querySelectorAll('input[name=order-type]');
    for (var i = 0; i < radios.length; i++) {
      if (radios[i].checked) { return radios[i].value; }
    }
    return '';
  }

  function submitOrder() {
    var tableRaw = $('table-no').value.trim();
    var table = parseInt(tableRaw, 10);
    if (!tableRaw || isNaN(table) || table < 1) {
      setMessage('order-message', 'テーブル番号を入力してください。', true);
      return;
    }
    var orderType = selectedOrderType();
    if (!orderType) {
      setMessage('order-message', '「店内」か「持ち帰り」を選んでください。', true);
      return;
    }
    var items = [];
    menu.forEach(function (m) {
      var q = quantities[m.id] || 0;
      if (q > 0 && !m.sold_out) { items.push({ id: m.id, quantity: q }); }
    });
    if (items.length === 0) {
      setMessage('order-message', '商品を1つ以上選んでください。', true);
      return;
    }
    var btn = $('submit-order');
    btn.disabled = true;
    api('orders', { method: 'POST', body: { table: table, order_type: orderType, items: items } }).then(function (data) {
      var o = data.order;
      setMessage('order-message', '注文を受け付けました(注文番号 ' + o.id + '、' + o.order_type + '、合計 ' + yen(o.total) + ')。', false);
      menu.forEach(function (m) { quantities[m.id] = 0; });
      updateCart();
    }).catch(function (e) {
      setMessage('order-message', '注文を送信できませんでした: ' + e.message, true);
      loadMenu();
    }).then(function () {
      btn.disabled = false;
    });
  }

  /* ---------- kitchen tab ---------- */
  function formatTime(iso) {
    var d = new Date(iso);
    if (isNaN(d.getTime())) { return ''; }
    return d.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Tokyo' });
  }

  function renderOrders(orders) {
    var filter = $('status-filter').value;
    var list = $('order-list');
    list.textContent = '';
    var shown = orders.filter(function (o) { return !filter || o.status === filter; });
    if (shown.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty';
      empty.textContent = '該当する注文はありません。';
      list.appendChild(empty);
      return;
    }
    shown.forEach(function (o) {
      var li = document.createElement('li');
      li.className = 'order ' + (STATUS_CLASS[o.status] || '');

      var head = document.createElement('div');
      head.className = 'order-head';
      var title = document.createElement('span');
      title.className = 'order-title';
      title.textContent = '注文 #' + o.id + ' / テーブル ' + o.table + ' ';
      var typeLabel = document.createElement('span');
      typeLabel.className = 'type-label ' + (TYPE_CLASS[o.order_type] || '');
      typeLabel.textContent = o.order_type || '';
      title.appendChild(typeLabel);
      var badge = document.createElement('span');
      badge.className = 'badge';
      badge.textContent = o.status;
      head.appendChild(title);
      head.appendChild(badge);

      var time = document.createElement('div');
      time.className = 'order-time';
      time.textContent = formatTime(o.created_at) + ' 受付';

      var ul = document.createElement('ul');
      ul.className = 'order-items';
      o.items.forEach(function (it) {
        var row = document.createElement('li');
        row.textContent = it.name + ' × ' + it.quantity;
        ul.appendChild(row);
      });

      var foot = document.createElement('div');
      foot.className = 'order-foot';
      var total = document.createElement('span');
      total.className = 'order-total';
      total.textContent = '合計 ' + yen(o.total);
      foot.appendChild(total);

      var next = STATUS_NEXT[o.status];
      if (next) {
        var b = document.createElement('button');
        b.type = 'button';
        b.className = 'primary';
        b.textContent = STATUS_BUTTON[o.status];
        b.addEventListener('click', function () { advance(o.id, next, b); });
        foot.appendChild(b);
      }

      li.appendChild(head);
      li.appendChild(time);
      li.appendChild(ul);
      li.appendChild(foot);
      list.appendChild(li);
    });
  }

  var lastOrders = [];

  function loadOrders() {
    return api('orders').then(function (data) {
      lastOrders = data.orders || [];
      renderOrders(lastOrders);
      setMessage('kitchen-message', '', false);
    }).catch(function (e) {
      setMessage('kitchen-message', '注文を読み込めませんでした: ' + e.message, true);
    });
  }

  function advance(id, next, btn) {
    btn.disabled = true;
    api('orders/' + id, { method: 'PATCH', body: { status: next } }).then(function () {
      return loadOrders();
    }).catch(function (e) {
      setMessage('kitchen-message', '状態を更新できませんでした: ' + e.message, true);
      btn.disabled = false;
    });
  }

  /* ---------- sales tab ---------- */
  function renderTopItems(items) {
    var list = $('top-items');
    list.textContent = '';
    if (!items || items.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty';
      empty.textContent = 'まだ販売がありません。';
      list.appendChild(empty);
      return;
    }
    items.forEach(function (it, idx) {
      var li = document.createElement('li');
      li.className = 'top-item rank-' + (idx + 1);
      var rank = document.createElement('span');
      rank.className = 'rank';
      rank.textContent = (idx + 1) + '位';
      var name = document.createElement('span');
      name.className = 'top-name';
      name.textContent = it.name;
      var count = document.createElement('span');
      count.className = 'top-count';
      count.textContent = it.quantity + '個';
      li.appendChild(rank);
      li.appendChild(name);
      li.appendChild(count);
      list.appendChild(li);
    });
  }

  function loadSales() {
    return api('sales/today').then(function (data) {
      $('sales-count').textContent = data.order_count + '件';
      $('sales-total').textContent = yen(data.total_sales);
      $('sales-date').textContent = data.date ? '対象日: ' + data.date + '(日本時間)' : '';
      renderTopItems(data.top_items);
      setMessage('sales-message', '', false);
    }).catch(function (e) {
      setMessage('sales-message', '売上を読み込めませんでした: ' + e.message, true);
    });
  }

  /* ---------- refresh ---------- */
  function refresh() {
    if (currentTab === 'kitchen') { loadOrders(); loadMenu(); }
    else if (currentTab === 'sales') { loadSales(); }
    else { loadMenu(); }
  }

  function init() {
    var tabs = document.querySelectorAll('.tab');
    for (var i = 0; i < tabs.length; i++) {
      (function (t) {
        t.addEventListener('click', function () { showTab(t.getAttribute('data-tab')); });
      })(tabs[i]);
    }
    $('submit-order').addEventListener('click', submitOrder);
    $('status-filter').addEventListener('change', function () { renderOrders(lastOrders); });
    loadMenu();
    setInterval(refresh, REFRESH_MS);
  }

  init();
})();

